<?php declare(strict_types=1); require_once __DIR__.'/../includes/bootstrap.php'; header('Content-Type: application/json; charset=utf-8'); $slug=trim((string)($_GET['slug']??'')); if($slug===''){http_response_code(400);echo json_encode(['ok'=>false,'error'=>'Lesson slug is required']);exit;} try{$q=$db->prepare("SELECT l.*,c.title course_title,c.slug course_slug,lc.name category_name FROM learning_lessons l JOIN learning_courses c ON c.id=l.course_id LEFT JOIN learning_categories lc ON lc.id=c.category_id WHERE l.slug=? AND l.enabled=1 AND c.enabled=1 LIMIT 1");$q->execute([$slug]);$lesson=$q->fetch(PDO::FETCH_ASSOC);if(!$lesson){http_response_code(404);echo json_encode(['ok'=>false,'error'=>'Lesson not found']);exit;} echo json_encode(['ok'=>true,'lesson'=>$lesson],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);}catch(Throwable $e){http_response_code(500);echo json_encode(['ok'=>false,'error'=>'Unable to load lesson']);}